🐛 Bug
original c10::Type::cast() function:
template<typename T>
  std::shared_ptr<const T> cast() const {
    std::shared_ptr<const T> r = nullptr;
    if (isSubclass(T::Kind)) {
      r = std::static_pointer_cast<const T>(shared_from_this());
    }
    if (!r || T::Kind == kind()) {
      return r;
    } else {
      return sliceType<T>(r);
    }
  }
I think  isSubclass(T::Kind) and T::Kind == kind() is Exactly the same, so in judge if (!r || T::Kind == kind()) the  T::Kind == kind() is Unnecessary which make the logic hard to understand;
Is the below implement right?
template<typename T>
  std::shared_ptr<const T> cast() const {
    std::shared_ptr<const T> r = nullptr;
    if (isSubclass(T::Kind)) {
      r = std::static_pointer_cast<const T>(shared_from_this());
    }
    if (!r) {
      return r;
    } else {
      return sliceType<T>(r);
    }
  }

